function normalizeTrustTier(value: unknown): PantavionTrustTier {
  switch (value) {
    case 'untrusted':
    case 'basic':
    case 'trusted':
    case 'high-trust':
    case 'system':
      return value;
    default:
      return 'basic';
  }
}

